import json
from pathlib import Path
from create_templates import resource,ref,att,sub
p=Path(__file__).parent
r={}
r['FailureQueue']=resource('AWS::SQS::Queue',{'SqsManagedSseEnabled':True,'MessageRetentionPeriod':1209600},'Retain failed scheduled invocations for diagnosis',retain=True)
r['ScanLock']=resource('AWS::DynamoDB::Table',{'BillingMode':'PAY_PER_REQUEST','AttributeDefinitions':[{'AttributeName':'id','AttributeType':'S'}],'KeySchema':[{'AttributeName':'id','KeyType':'HASH'}],'SSESpecification':{'SSEEnabled':True},'TimeToLiveSpecification':{'AttributeName':'expires','Enabled':True}},'Atomic short-lived lease prevents overlapping scans without reserving sandbox concurrency',retain=True)
r['MonitorRole']=resource('AWS::IAM::Role',{'AssumeRolePolicyDocument':{'Version':'2012-10-17','Statement':[{'Effect':'Allow','Principal':{'Service':'lambda.amazonaws.com'},'Action':'sts:AssumeRole'}]},'Policies':[{'PolicyName':'MonitorScopedData','PolicyDocument':{'Version':'2012-10-17','Statement':[{'Effect':'Allow','Action':'s3:GetObject','Resource':[sub('arn:${AWS::Partition}:s3:::${DataBucket}/site/data/baseline.json'),sub('arn:${AWS::Partition}:s3:::${DataBucket}/site/data/monitor.json'),sub('arn:${AWS::Partition}:s3:::${DataBucket}/private/state.json')]},{'Effect':'Allow','Action':'s3:PutObject','Resource':[sub('arn:${AWS::Partition}:s3:::${DataBucket}/site/data/monitor.json'),sub('arn:${AWS::Partition}:s3:::${DataBucket}/site/api/monitor'),sub('arn:${AWS::Partition}:s3:::${DataBucket}/private/state.json'),sub('arn:${AWS::Partition}:s3:::${DataBucket}/private/snapshots/*')]},{'Effect':'Allow','Action':['logs:CreateLogStream','logs:PutLogEvents'],'Resource':sub('arn:${AWS::Partition}:logs:${AWS::Region}:${AWS::AccountId}:log-group:/aws/lambda/${AWS::StackName}-crawler:*')},{'Effect':'Allow','Action':'sqs:SendMessage','Resource':att('FailureQueue','Arn')},{'Effect':'Allow','Action':['dynamodb:PutItem','dynamodb:DeleteItem'],'Resource':att('ScanLock','Arn')}]}}]},'Allow public-source monitoring to update only its data and private evidence prefixes',['No IAM, patient records, or unrelated buckets accessible'])
r['LogGroup']=resource('AWS::Logs::LogGroup',{'LogGroupName':sub('/aws/lambda/${AWS::StackName}-crawler'),'RetentionInDays':14},'Bounded operational logs; no retrieved page bodies logged')
r['MonitorFunction']=resource('AWS::Lambda::Function',{'FunctionName':sub('${AWS::StackName}-crawler'),'Runtime':'python3.12','Handler':'handler.handler','Role':att('MonitorRole','Arn'),'Code':{'S3Bucket':ref('DataBucket'),'S3Key':ref('CodeKey')},'Timeout':300,'MemorySize':512,'Environment':{'Variables':{'DATA_BUCKET':ref('DataBucket'),'LOCK_TABLE':ref('ScanLock')}},'DeadLetterConfig':{'TargetArn':att('FailureQueue','Arn')},'Architectures':['x86_64']},'Hourly bounded crawler; deterministic evidence candidates avoid automated legal verdicts',['Never overwrite baseline grades','Reject private addresses and off-host document redirects'])
r['MonitorFunction']['DependsOn']=['LogGroup']
r['ScheduleGroup']=resource('AWS::Scheduler::ScheduleGroup',{'Name':sub('${AWS::StackName}-group')},'Isolate scheduler trust to this application group')
r['SchedulerRole']=resource('AWS::IAM::Role',{'AssumeRolePolicyDocument':{'Version':'2012-10-17','Statement':[{'Effect':'Allow','Principal':{'Service':'scheduler.amazonaws.com'},'Action':'sts:AssumeRole','Condition':{'StringEquals':{'aws:SourceAccount':ref('AWS::AccountId')},'ArnEquals':{'aws:SourceArn':att('ScheduleGroup','Arn')}}}]},'Policies':[{'PolicyName':'InvokeOnlyMonitor','PolicyDocument':{'Version':'2012-10-17','Statement':[{'Effect':'Allow','Action':'lambda:InvokeFunction','Resource':att('MonitorFunction','Arn')},{'Effect':'Allow','Action':'sqs:SendMessage','Resource':att('FailureQueue','Arn')}]}}]},'Permit this schedule group to invoke only the monitor',['No generic invoke or cross-account trust'])
r['HourlyScan']=resource('AWS::Scheduler::Schedule',{'GroupName':ref('ScheduleGroup'),'ScheduleExpression':'rate(1 hour)','FlexibleTimeWindow':{'Mode':'OFF'},'State':'ENABLED','Target':{'Arn':att('MonitorFunction','Arn'),'RoleArn':att('SchedulerRole','Arn'),'Input':'{}','RetryPolicy':{'MaximumEventAgeInSeconds':3600,'MaximumRetryAttempts':1},'DeadLetterConfig':{'Arn':att('FailureQueue','Arn')}}},'Scan a rotating batch of four source pages each hour; bounded costs and crawl rate')
r['ErrorAlarm']=resource('AWS::CloudWatch::Alarm',{'AlarmDescription':'Investigate monitor execution errors in the application log group','Namespace':'AWS/Lambda','MetricName':'Errors','Dimensions':[{'Name':'FunctionName','Value':ref('MonitorFunction')}],'Statistic':'Sum','Period':3600,'EvaluationPeriods':1,'Threshold':1,'ComparisonOperator':'GreaterThanOrEqualToThreshold','TreatMissingData':'notBreaching'},'Expose failures in CloudWatch without unsolicited notifications')
t={'AWSTemplateFormatVersion':'2010-09-09','Description':'CareWatch NY policy monitor - bounded scheduled public-source checks with private evidence snapshots and no automatic legal grades.','Metadata':{'AWSToolsMetrics':{'AWSAgentToolkit':'aws-cloudformation@3'}},'Parameters':{'DataBucket':{'Type':'String','Description':'Existing private CareWatch application bucket'},'CodeKey':{'Type':'String','Description':'Versioned monitor ZIP object key'}},'Resources':r,'Outputs':{'FunctionName':{'Value':ref('MonitorFunction'),'Description':'Scheduled source-monitor function'},'ScheduleName':{'Value':ref('HourlyScan'),'Description':'Hourly source-check schedule'}}}
(p/'monitoring.json').write_text(json.dumps(t,indent=2))
